# find longest even palindromic stem allowed hairpin
def longest_stem(i0):
    # try symmetric loops of 3..8 bp
    best = (0,None)
    for loop in range(3,9):
        d = 0
        while True:
            a = i0-d-1; b = i0+loop+d
            if a < 0 or b >= L: break
            if seq[a] == seq[b].translate(str.maketrans("ACGT","TGCA")):
                d += 1
            else:
                break
        if d > best[0]:
            best = (d, loop)
    return best

best_all = (0,None,None)
for i in range(L):
    d, loop = longest_stem(i)
    if d >= 13:
        a = i-d; b = i+loop+d
        sub = seq[a:b]
        if "GATAAACCG" in sub:
            print("big hairpin: start_pos", a+1, "end_pos", b, "stem", d, "loop", loop, "seq", sub)

# crude max-stats
maxd=0; arg=None
for i in range(L):
    d, loop = longest_stem(i)
    if d>maxd:
        maxd=d; arg=(i+1,)
print("max dyad stem found:", maxd, "at loop center pos", arg)
