import re
seq = ''
with open('region.fasta') as f:
    f.readline()
    for l in f:
        seq += l.strip()

# ---- Overall structure: motif ORFs ----
motif = "AGTTCCCCGCGCCAGCGGGGATAAACCG"

# 1. ORFs in all frames of the main sequence (forward and reverse)
def revcomp(s): return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

def find_orfs(s, minlen=90):
    stops = {'TAA','TAG','TGA'}
    out=[]
    for strand, ss in [("fwd", s), ("rev", revcomp(s))]:
        L=len(ss)
        for frame in range(3):
            i=frame
            while i < L-2:
                if ss[i:i+3]=='ATG':
                    j=i
                    while j < L-2:
                        if ss[j:j+3] in stops:
                            L_orf=j-i
                            if L_orf >= minlen:
                                if strand=="fwd":
                                    out.append((i+1, j+3, L_orf, strand))
                                else:
                                    out.append((L-1-i+1, L-j, L_orf, strand))  # positions mapping
                            i=j+3
                            break
                        j+=3
                    else:
                        if L-i >= minlen:
                            if strand=="fwd":
                                out.append((i+1, L, L-i, strand))
                            else:
                                out.append((L-i, 1, L-i, strand))
                        i+=3
                else:
                    i+=3
    return out

orf_list = find_orfs(seq, minlen=90)  # >= 30 aa
orf_list.sort(key=lambda x:-x[2])
print("=== ORFs >= 30 codons (top by length, max 20) ===")
for o in orf_list[:20]:
    print("  strand {0}  from {1} to {2}  ({3} nt)".format(o[3], min(o[0],o[1]), max(o[0],o[1]), o[2]))

# 2. area around each motif: is there a start codon right before, or inside?
print("\nStart codon context around each motif:")
for s in [m.start() for m in re.finditer(motif, seq)]:
    ctx_pre = seq[s-20:s]
    # look for ATG/GTG/TTG as alternative starts within 20 bp
    cands = [m.start() for m in re.finditer('(?=ATG|GTG|TTG)', seq[max(0,s-20):s])]
    abs_pos = [s-20+c+1 for c in cands]
    print("  motif@", s+1, "starts nearby:", abs_pos)
